const products = [
  {id:'soil',name:'Soil Revive',category:'soil',label:'Soil care',detail:'Organic soil conditioner',weight:'5 kg',price:549,color:'#526848',badge:'Start with the soil',formula:'SOIL CONDITIONER'},
  {id:'grow',name:'Grow Balanced',category:'growth',label:'Crop growth',detail:'NPK 19:19:19 · Water soluble',weight:'1 kg',price:399,color:'#b59850',badge:'Balanced nutrition',formula:'NPK 19 : 19 : 19'},
  {id:'root',name:'Root & Rise',category:'growth',label:'Crop growth',detail:'NPK 12:61:00 · Water soluble',weight:'1 kg',price:449,color:'#3f675a',badge:'Root-stage nutrition',formula:'NPK 12 : 61 : 00'},
  {id:'micro',name:'Micro Essentials',category:'specialty',label:'Specialty nutrition',detail:'Micronutrient blend',weight:'500 g',price:299,color:'#946b47',badge:'The finer details',formula:'MICRONUTRIENT BLEND'},
  {id:'bloom',name:'Bloom & Beyond',category:'specialty',label:'Specialty nutrition',detail:'NPK 00:00:50 · Water soluble',weight:'1 kg',price:479,color:'#868345',badge:'A new growth chapter',formula:'NPK 00 : 00 : 50'},
  {id:'earth',name:'Earth Balance',category:'soil',label:'Soil care',detail:'Illustrative soil care blend',weight:'5 kg',price:649,color:'#4d7560',badge:'Grounded in care',formula:'SOIL CARE BLEND'}
];
const money = value => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(value);
let cart = {};
try { const saved=JSON.parse(localStorage.getItem('avigna-bag')||'{}'); for(const p of products) if(Number.isInteger(saved[p.id])&&saved[p.id]>0) cart[p.id]=Math.min(saved[p.id],99); } catch {}
let currentFilter='all'; let lastFocus; let toastTimer;
const $=selector=>document.querySelector(selector);
function showToast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function renderProducts(){let list=products.filter(p=>(currentFilter==='all'||p.category===currentFilter)&&`${p.name} ${p.detail} ${p.label}`.toLowerCase().includes($('#search-input').value.toLowerCase().trim()));if($('#sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')list.sort((a,b)=>b.price-a.price);$('#product-grid').innerHTML=list.map(p=>`<article class="product-card"><div class="product-image"><span class="product-badge">${p.badge}</span><div class="pack" style="--pack-color:${p.color}" aria-label="Illustrative ${p.name} packaging"><img src="assets/logo.svg" alt=""><div class="pack-band"><small>CROP NUTRITION</small><strong>${p.name.replace(' ','<br>')}</strong><span>${p.formula}</span><span class="pack-leaf">❧</span></div><span class="pack-weight">NET WEIGHT ${p.weight.toUpperCase()}</span></div></div><div class="product-info"><span class="product-category">${p.label} / ${p.weight}</span><h3>${p.name}</h3><p class="product-detail">${p.detail}</p><div class="product-bottom"><span>${money(p.price)} <small>/ pack</small></span><button class="add-button" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div></div></article>`).join('')||'<p class="no-products">No products found. Try another search or category.</p>'}
function saveCart(){const focused=document.activeElement;const quantityId=focused?.dataset?.quantity;const change=focused?.dataset?.change;const removeId=focused?.dataset?.remove;try{localStorage.setItem('avigna-bag',JSON.stringify(cart))}catch{}renderCart();if(quantityId){const next=document.querySelector(`[data-quantity="${quantityId}"][data-change="${change}"]`);(next||$('#cart-close')).focus({preventScroll:true})}else if(removeId){$('#cart-close').focus({preventScroll:true})}}
function renderCart(){const items=products.filter(p=>cart[p.id]);$('#cart-count').textContent=items.reduce((sum,p)=>sum+cart[p.id],0);$('#cart-items').innerHTML=items.length?items.map(p=>`<div class="cart-item"><div class="cart-swatch" style="--item-color:${p.color}">❧</div><div class="cart-item-content"><h3>${p.name}</h3><p>${p.weight} · ${money(p.price)} / pack</p><div class="quantity"><button data-quantity="${p.id}" data-change="-1" aria-label="Decrease ${p.name} quantity">−</button><span>${cart[p.id]}</span><button data-quantity="${p.id}" data-change="1" aria-label="Increase ${p.name} quantity">+</button><button class="remove-item" data-remove="${p.id}" aria-label="Remove ${p.name}">×</button></div></div><strong>${money(p.price*cart[p.id])}</strong></div>`).join(''):'<div class="empty-cart"><span>❧</span><h3>Good growth starts here.</h3><p>Your bag is waiting for a little nutrition.<br>Explore the collection to get started.</p><button class="button green" id="continue-shopping">Explore nutrition ↗</button></div>';$('#cart-summary').innerHTML=items.length?`<div class="cart-total"><span>Subtotal</span><strong>${money(items.reduce((sum,p)=>sum+p.price*cart[p.id],0))}</strong></div><button class="button green checkout" id="checkout">Review demo order <span>↗</span></button><p class="checkout-note">Illustrative prices. This is a frontend preview; no payment or real order will be processed.</p><div id="order-result" hidden></div>`:''}
function openCart(){lastFocus=document.activeElement;$('#cart-drawer').hidden=false;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#cart-close').focus()}
function closeCart(){$('#cart-drawer').hidden=true;$('#overlay').hidden=true;document.body.style.overflow='';lastFocus?.focus()}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){cart[add.dataset.add]=Math.min((cart[add.dataset.add]||0)+1,99);saveCart();showToast(`${products.find(p=>p.id===add.dataset.add).name} added to your bag`)}const quantity=e.target.closest('[data-quantity]');if(quantity){const id=quantity.dataset.quantity;cart[id]=Math.min(cart[id]+Number(quantity.dataset.change),99);if(cart[id]<=0)delete cart[id];saveCart()}const remove=e.target.closest('[data-remove]');if(remove){delete cart[remove.dataset.remove];saveCart()}const service=e.target.closest('[data-service]');if(service){$('#service-select').value=service.dataset.service;$('#enquiry-result').hidden=true;$('#service-dialog').showModal()}if(e.target.closest('#continue-shopping')){closeCart();location.hash='shop'}if(e.target.closest('nav a')){$('nav').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false')}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{currentFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProducts()}));
$('#sort').addEventListener('change',()=>renderProducts());$('#search-input').addEventListener('input',()=>renderProducts());$('#search-button').addEventListener('click',()=>{$('#search-row').hidden=false;document.querySelector('#shop').scrollIntoView();$('#search-input').focus({preventScroll:true})});$('#search-close').addEventListener('click',()=>{$('#search-input').value='';$('#search-row').hidden=true;renderProducts()});$('#cart-button').addEventListener('click',openCart);$('#cart-close').addEventListener('click',closeCart);$('#overlay').addEventListener('click',closeCart);$('.dialog-close').addEventListener('click',()=>$('#service-dialog').close());$('#menu-button').setAttribute('aria-expanded','false');$('#menu-button').addEventListener('click',()=>{$('nav').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String($('nav').classList.contains('open')))});
document.addEventListener('keydown',e=>{if($('#cart-drawer').hidden)return;if(e.key==='Escape')closeCart();if(e.key==='Tab'){const focusables=[...$('#cart-drawer').querySelectorAll('button,a,input,select')];const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const result=$('#enquiry-result');result.replaceChildren();const heading=document.createElement('strong');heading.textContent='Your enquiry preview';const text=document.createElement('p');text.textContent=`${data.get('name')} · ${data.get('phone')} · ${data.get('location')}`;const interest=document.createElement('p');interest.textContent=$('#service-select').value;const message=document.createElement('p');message.textContent=data.get('message');const note=document.createElement('p');note.textContent='Preview only — this enquiry has not been sent.';result.append(heading,text,interest,message,note);result.hidden=false;result.scrollIntoView({block:'nearest',behavior:'smooth'})});
$('#year').textContent=new Date().getFullYear();document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));renderProducts();renderCart();
